entries[215142] = { ["name"] = "Freydrins Shillelagh", ["text"] = "Questgegenstand\nBenutzen: Bannt Faulborkes 'Fäulnisraserei'.\nVerringert die Gesundheit des Ziels um 10%. (16 Sek. Abklingzeit)\n73 ( 73)\n\"Eine jenseitige Lebensenergie schwingt durch den Wald.\"" }
entries[215143] = { ["name"] = "Copy Copy Elemental Lariat", ["text"] = "Wird beim Aufheben gebunden\nHals\n+234 Ausdauer\n+ 360 Zufallswert 1\n+ 360 Zufallswert 2\nVerkaufspreis:" }
