entries[215145] = { ["name"] = "Gedenkstein", ["text"] = "Spielzeug\nBenutzen: Bereitet einem gefallenen Spielercharakter ein respektvolles Begräbnis. (5 Min Abklingzeit)\n\"Seid immer vorbereitet.\"\nVerkaufspreis:" }
entries[215147] = { ["name"] = "Verschönerungsiris", ["text"] = "Spielzeug\nBenutzen: Fokussiert einen farbenfrohen Lichtstrahl durch einen Edelstein auf ein hilfloses Kleintier. (10 Min Abklingzeit)\n\"Die Welt ist grässlich, aber das heißt nicht, dass sie auch hässlich sein muss.\"\nVerkaufspreis:" }
entries[215158] = { ["name"] = "Freydrins Shillelagh", ["text"] = "Questgegenstand\nBenutzen: Entfesselt Freyas Lebensmagie auf die Wildnis. (6 Sek. Abklingzeit)\n73 ( 73)\n\"Eine jenseitige Lebensenergie schwingt durch den Wald.\"" }
entries[215159] = { ["name"] = "Geplünderte Trophäe", ["text"] = "Questgegenstand\nEinzigartig (6)\n<Zum Lesen rechtsklicken>" }
entries[215160] = { ["name"] = "Der große Buddelschmuddel", ["text"] = "Wird beim Aufheben gebunden\n\"Die einzige Kiste, die robust genug ist, Verdammnisschatten zu überleben. Enthält viele seltene Artefakte und Vorräte.\"\n<Zum Öffnen rechtsklicken>" }
entries[215164] = { ["name"] = "Ei der Brutmutter", ["text"] = "Questgegenstand\n\"Fühlt sich schwerer als gewöhnliche Larveneier an.\"" }
entries[215169] = { ["name"] = "Ewig brennende Laterne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 [Beweglichkeit oder Intelligenz]\nAnlegen: Eure schädlichen Distanzkampfzauber und -fähigkeiten haben eine hohe Chance, die Flamme der Laterne zu schüren. Gewährt bis zu 15-mal einen Stapel 'Lampenlicht'.\n\nNach 30 Sek. werden die gesammelten Stapel von 'Lampenlicht' verbraucht, um eine entsprechende Anzahl an Glühwürmchen anzuziehen. Die Glühwürmchen stürzen sich auf das nächste Ziel, das Ihr angreift, explodieren und verursachen pro Glühwürmchen ( 1 * 151 ) Feuerschaden.\nVerkaufspreis:" }
entries[215170] = { ["name"] = "Abgrundfalle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 [Beweglichkeit oder Stärke]\nBenutzen: Platziert eine Abgrundfalle zu Euren Füßen. Wenn sich ein Gegner bis auf 3 Meter nähert, wird für 10 Sek. eine riesige Wasserblase erzeugt. Alle Gegner innerhalb der Blase erleiden pro Sekunde ( 1 * 195 ) Frostschaden.\n\nDie Falle bleibt 1 Min. lang bestehen, bevor sie automatisch entschärft wird. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[215171] = { ["name"] = "Flöte des Fungusfreunds", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 Intelligenz\nAnlegen: Zauber und Fähigkeiten haben eine Chance, dass sich ein farbenprächtiger Fungusfreund aus der Erde emporgräbt, der Verbündete um 4513 Gesundheit heilt, Euch 439 Mana gewährt oder einem Gegner in der Nähe im Verlauf von 3 Sek. ( 1028 * 3) Naturschaden zufügt. (1s Abklingzeit)\n\"Fungusfreunde sterben niemals so ganz. Stattdessen sickern ihre Sporen zurück in die Erde und bringen den Freund erneut hervor.\"\nVerkaufspreis:" }
entries[215172] = { ["name"] = "Seidenkettenweber", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 [Beweglichkeit oder Stärke]\nBenutzen: Entfaltet unzählige klebrige Spinnweben vor Euch, die Eure Gegner umwickeln. Dies reduziert den Schaden, den sie Euch zufügen, um 30% bis maximal 5255 Gesamtschaden und verringert ihr Angriffstempo um 15%. Hält 15 Sek. lang an.\n\n[Die Verringerung des Angriffstempos ist bei Gegnern über Stufe 80 weniger effektiv.] (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[215173] = { ["name"] = "Serum der zügellosen Sinneseindrücke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+ 48 Ausweichen\n+ 48 Parieren\nAnlegen: Konsumiert methodisch eine kleine Dose des Serums, wenn Ihr Euch in den Kampf stürzt, um Eure Sinne bis an ihre Grenzen zu schärfen.\nIn diesem Zustand besteht beim Parieren und Ausweichen eine Chance, dem Angreifer mit 'Konter' zu begegnen und ihm Y körperlichen Schaden zufügen.\n\"Mögliche Nebenwirkungen umfassen Gleichgewichtsverlust, Erbrechen, extreme Schmerzen, kurzfristigen Gedächtnisverlust, langfristigen Gedächtnisverlust, Verlust von motorischen Funktionen, Halluzinationen und einen unstillbaren Appetit auf kleine Insekten.\"\nVerkaufspreis:" }
entries[215174] = { ["name"] = "Mixtur: Kuss des Todes", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Trinkt aus der Phiole, damit die Toxine durch Eure Adern zirkulieren und alle Sekundärwerte 30 Sek. lang um 106 erhöhen.\n\nSpringt, um Euch das Gegengift zu verabreichen und den Effekt zu beenden.\n\nWenn Ihr das Gegengift nicht vor Ablauf des Effekts einnehmt, werdet Ihr für 5 Sek. betäubt. (2 Min, 30 Sek. Abklingzeit)\n\"WARNUNG: Bei Ausbleiben einer Dosis Gegengift kurz nach Einnahme kann der Tod eintreten.\"\nVerkaufspreis:" }
entries[215175] = { ["name"] = "Phiolengurt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+64 [Beweglichkeit oder Intelligenz]\nVerkaufspreis:" }
entries[215176] = { ["name"] = "Ensemble: Gewänder des Brisenbinders", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Sammelt die Vorlagen dieses Rüstungssets.\n\nDiese Vorlagen können nur von Magiern, Priestern und Hexenmeistern verwendet werden." }
entries[215177] = { ["name"] = "Energiezelle", ["text"] = "Questgegenstand\n\"Die Goldfassung der Zelle ist beschädigt, doch die staubige Zelle brummt nach wie vor leicht in Eurer Hand. Vielleicht befindet sich noch etwas Energie darin.\"" }
entries[215178] = { ["name"] = "Schattenbindendes Ritualmesser", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 96.\nAnlegen: Graviert ein Ritualsiegel in Eure Haut, das Euch an die Schatten bindet und 73 Hauptwert gewährt.\n\nEure Zauber und Fähigkeiten haben eine geringe Chance, einen Eurer Sekundärwerte im Kampf 10 Sek. lang um 265 zu verringern.\nVerkaufspreis:" }
