entries[215359] = { ["name"] = "Sehr großes Vorratspaket des Valdrakkenabkommens", ["text"] = "Wird beim Aufheben gebunden\n\"Beinhaltet Vorräte der Dracheninseln, die gegen Fraktionsgegenstände eingetauscht oder zur Förderung von Fertigkeiten für Fraktionstätigkeiten eingesetzt werden können.\"\n<Zum Öffnen rechtsklicken>" }
entries[215360] = { ["name"] = "Personalisierte Einstellung" }
entries[215361] = { ["name"] = "Bebensprung", ["text"] = "Schildhand\nEinzigartig anlegbar\nAusrüstbarer Zauber - Strategisch" }
entries[215362] = { ["name"] = "Truhe der Stürme", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Enthält ein zufälliges Stück Veteranenausrüstung, Gold und Materialien zur Ausrüstungsverbesserung.\"\n<Zum Öffnen rechtsklicken>" }
entries[215363] = { ["name"] = "Funkenlager", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Enthält ein zufälliges Stück Veteranenausrüstung, Gold und Materialien zur Ausrüstungsverbesserung.\"\n<Zum Öffnen rechtsklicken>" }
entries[215364] = { ["name"] = "Traumlager", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Enthält ein zufälliges Stück Veteranenausrüstung, Gold und Materialien zur Ausrüstungsverbesserung.\"\n<Zum Öffnen rechtsklicken>" }
entries[215438] = { ["name"] = "Chronoabzeichen", ["text"] = "Questgegenstand\nEinzigartig\n80 ( 80)\n\"Ihr Ticken scheint mit Eurem Herzschlag synchronisiert zu sein. Wo hat Horos so etwas gefunden?\"" }
entries[215442] = { ["name"] = "Umhang des ewigen Potenzials", ["text"] = "Questgegenstand\nEinzigartig\n80 ( 80)\n\"Er scheint aus sich ständig bewegendem Sand zu bestehen.\"" }
entries[215446] = { ["name"] = "Ramponierter Helm", ["text"] = "Questgegenstand\nEinzigartig\n\"Hat sicherlich eine Menge mitgemacht. Er ist mehrere Male liebevoll ausgebessert worden.\"" }
entries[215447] = { ["name"] = "Dämmerstiel", ["text"] = "Questgegenstand" }
entries[215448] = { ["name"] = "Finsterstammeintopf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (100)\nBenutzen: Stellt im Verlauf von 20 Sek. ( 80357 / 5 * 20) Gesundheit wieder her. Ihr müsst beim Essen sitzen bleiben. Wenn Ihr mindestens 10 Sek. mit Essen verbringt, erhaltet Ihr den Effekt 'Finsterstammeintopf'. Angriffe auf Euch haben eine Chance, Euch Gegnern innerhalb von 10 Metern 7 Naturschaden zufügen zu lassen.\n\nVerwendbar in Blüte des Lichts und nahen Schlüsselflammengebieten." }
entries[215455] = { ["name"] = "Ketten des Jägers", ["text"] = "Schildhand\nEinzigartig anlegbar\nAusrüstbarer Zauber - Strategisch" }
entries[215457] = { ["name"] = "Absonderungen der Loyalisten", ["text"] = "Questgegenstand\n80 ( 80)\n\"Wird ausschließlich in den Pheromondrüsen der vertrauenswürdigsten Akolythen der Sureki gefunden.\"" }
entries[215464] = { ["name"] = "Fragment eines Erinnerungsedelsteins", ["text"] = "Questgegenstand\nEinzigartig\n\"Matt und mit spinnwebenartigen Rissen durchzogen. Der Edelsteinteil ist so gebrochen, dass er in Eurer Hand zerfallen könnte. Der ursprüngliche Edelstein muss beträchtlichen Schaden erlitten haben. Der ist nicht mehr zu retten.\"" }
entries[215466] = { ["name"] = "Geheiligte Vorräte", ["text"] = "\"Diese Vorräte sind in der Lage, die Barrieren der Finsternis in der Umgebung zu zerstreuen.\"" }
entries[215467] = { ["name"] = "Dreckbersterhacke", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Schwingt eine große Spitzhacke gen Boden, wodurch alle Kreaturen in der Nähe aus dem Erdreich emporkommen." }
